<?php defined( 'ABSPATH' ) || exit; get_header(); ?>
<main id="main" class="container page-main narrow"><?php while ( have_posts() ) : the_post(); ?><article <?php post_class(); ?>><p class="eyebrow"><?php echo esc_html( get_the_date() ); ?></p><h1 class="page-title"><?php the_title(); ?></h1><?php if ( has_post_thumbnail() ) { the_post_thumbnail( 'large', array( 'class' => 'post-cover' ) ); } ?><div class="entry-content"><?php the_content(); wp_link_pages(); ?></div><?php the_post_navigation(); ?></article><?php if ( comments_open() || get_comments_number() ) { comments_template(); } endwhile; ?></main><?php get_footer(); ?>
